object QiblaMath {
    fun bearing(latitude: Double, longitude: Double): Double {
        require(latitude.isFinite() && longitude.isFinite() && latitude in -90.0..90.0 && longitude in -180.0..180.0)
        val lat = Math.toRadians(latitude)
        val kaaba = Math.toRadians(21.422487)
        val delta = Math.toRadians(39.826206 - longitude)
        return (Math.toDegrees(atan2(sin(delta), cos(lat) * tan(kaaba) - sin(lat) * cos(delta))) + 360) % 360
    }
}
